        From 8671ea99241cb421e60f94c70da906b118e5da52 Mon Sep 17 00:00:00 2001
From: jeanlf <jeanlf@users.sourceforge.net>
Date: Tue, 27 Aug 2019 15:28:34 +0200
Subject: [PATCH] fixed bugs introduced by 6a089b5

---
 src/filters/mux_isom.c        | 8 +-------
 src/media_tools/crypt_tools.c | 6 +++---
 2 files changed, 4 insertions(+), 10 deletions(-)

diff --git a/src/filters/mux_isom.c b/src/filters/mux_isom.c
index 84aaf9c0d..b7ac0a89b 100644
--- a/src/filters/mux_isom.c
+++ b/src/filters/mux_isom.c
@@ -3125,7 +3125,7 @@ static GF_Err mp4_mux_initialize_movie(GF_MP4MuxCtx *ctx)
 	max_dur.den = 1;
 	max_dur.num = 0;

-	if (ctx->sseg)
+	if (ctx->sseg && ctx->noinit)
 		ctx->single_file = GF_FALSE;

 	if (ctx->idur.num && ctx->idur.den) {
@@ -4206,12 +4206,6 @@ static GF_Err mp4_mux_initialize(GF_Filter *filter)
 		u32 open_mode = GF_ISOM_OPEN_WRITE;
 		ctx->owns_mov = GF_TRUE;

-		if (ctx->sseg) {
-			ctx->noinit = GF_TRUE;
-			ctx->cdur = 1000000000;
-			ctx->store = MP4MX_MODE_FRAG;
-		}
-
 		switch (ctx->store) {
 		case MP4MX_MODE_INTER:
 		case MP4MX_MODE_TIGHT:
diff --git a/src/media_tools/crypt_tools.c b/src/media_tools/crypt_tools.c
index 1ab8e092d..fe147a783 100644
--- a/src/media_tools/crypt_tools.c
+++ b/src/media_tools/crypt_tools.c
@@ -534,9 +534,9 @@ static GF_Err gf_crypt_file_ex(GF_ISOFile *mp4, const char *drm_file, const char
 	}

 	gf_dynstrcat(&szArgs, "SID=1", NULL);
-	if (fragment_name)
-		gf_dynstrcat(&szArgs, ":sseg", NULL);
-	else {
+	if (fragment_name) {
+		gf_dynstrcat(&szArgs, ":sseg:noinit:store=frag:cdur=1000000000", NULL);
+	} else {
 		if (interleave_time) {
 			sprintf(an_arg, ":cdur=%g", interleave_time);
 			gf_dynstrcat(&szArgs, an_arg, NULL);
-- 
